import XCTest

final class TapTests: XCTestCase {
    func testOpenNotifications() {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let safari = XCUIApplication(bundleIdentifier: "com.apple.mobilesafari")
        let bluesky = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")

        sleep(1)
        var tapped = false
        for app in [springboard, safari, bluesky] {
            let button = app.alerts.firstMatch.buttons["Open"]
            if button.waitForExistence(timeout: 2) {
                button.tap()
                tapped = true
                break
            }
        }
        if !tapped {
            springboard.coordinate(withNormalizedOffset: CGVector(dx: 0.672, dy: 0.55)).tap()
        }
        sleep(3)

        bluesky.activate()
        sleep(2)

        let frame = bluesky.frame
        let bell = bluesky.coordinate(withNormalizedOffset: CGVector(dx: 0.691, dy: 0.935))
        bell.tap()
        sleep(3)
    }
}
EOF
